svg.addEventListener('keydown',e=>{if(mode==='board'&&boardEvents.keydown(e))return;const rotate=e.target.closest('[data-rotate]');if(rotate&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.stopPropagation();rotateComponent(rotate.dataset.rotate);}});
svg.addEventListener('pointermove',e=>{if(mode==='board'&&boardEvents.move(e))return;if(wireGesture&&wireGesture.pointerId===e.pointerId){const p=pointer(e);if(!wireGesture.moved&&((p.x-wireGesture.start.x)**2+(p.y-wireGesture.start.y)**2)>16){wireGesture.moved=true;pending=null;}if(wireGesture.moved)updateWirePreview(p);return;}if(pan&&pan.pointerId===e.pointerId){view.x=pan.vx-(e.clientX-pan.clientX)*pan.ux;view.y=pan.vy-(e.clientY-pan.clientY)*pan.uy;render();return;}if(!drag||drag.pointerId!==e.pointerId)return;const p=pointer(e),c=project.components.find(c=>c.id===drag.id);c.x=Math.max(90,Math.min(780,Math.round((p.x-drag.dx)/10)*10));c.y=Math.max(90,Math.min(460,Math.round((p.y-drag.dy)/10)*10));render();});
svg.addEventListener('pointerup',e=>{if(mode==='board'&&boardEvents.up(e))return;if(wireGesture){finishWireGesture(e);return;}if(drag?.pointerId===e.pointerId){drag=null;render();}if(pan?.pointerId===e.pointerId)pan=null;});
function cancelActiveGesture(){if(mode==='board')boardEvents.cancel();if(wireGesture){clearWireGesture({clearPending:true});render();tell('Connection gesture cancelled.');}drag=null;pan=null;}
svg.addEventListener('pointercancel',e=>{if(mode==='board')boardEvents.cancel();cancelActiveGesture();});svg.addEventListener('lostpointercapture',e=>{if(wireGesture?.pointerId===e.pointerId)cancelActiveGesture();if(drag?.pointerId===e.pointerId)drag=null;if(pan?.pointerId===e.pointerId)pan=null;});
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(project.components.length>=60){tell('This version supports 60 components.');return;}checkpoint();const type=b.dataset.add,id=crypto.randomUUID(),prefix={resistor:'R',capacitor:'C',source:'V',ground:'GND'}[type];project.components.push({id,type,label:prefix+(type==='ground'?'':project.components.filter(c=>c.type===type).length+1),value:{resistor:1000,capacitor:.000001,source:5,ground:0}[type],x:300+Math.round(Math.random()*20)*10,y:230});invalidateBoard(project);selected=id;mode='design';render();tell('Component added. Drag it into place, then connect its pins.');});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{boardEvents.cancel();clearWireGesture({clearPending:true});drag=null;pan=null;mode=b.dataset.tab;pending=null;boardSelection={component:null,track:null};boardIssues=[];if(mode==='board')ensureBoard(project);render();if(mode==='board')tell('Drag parts into place. Pull a dot to its matching dot. Dashed lines show what still needs connecting.');});
$('#undo').onclick=()=>{if(history.length){boardEvents.cancel();clearWireGesture({clearPending:true});drag=null;pan=null;project=JSON.parse(history.pop());pending=null;result=null;render();tell('Undone.');}};
$('#reset').onclick=()=>{boardEvents.cancel();clearWireGesture({clearPending:true});drag=null;pan=null;checkpoint();project={...project,components:[],wires:[],board:{width:60,height:40,placements:{},tracks:[]}};boardSelection={component:null,track:null};boardIssues=[];selected=null;pending=null;mode='design';render();tell('All components and wires cleared. Undo to restore.');};
$('#project-name').onchange=e=>{checkpoint();project.name=e.target.value.slice(0,80);persist();};
$('#run').onclick=()=>{try{const dc=solve(project);result=solve(project,{transient:true});mode='simulate';render();showResults(dc,result);tell('Simulation complete. Results reflect your connected circuit.');}catch(e){$('#results').replaceChildren();tell(e.message);}};
function showResults(dc,tr){const host=$('#results');host.replaceChildren();const analysis=$('.analysis-type');if(analysis)analysis.textContent='DC + STEP RESPONSE';const capacitor=project.components.find(c=>c.type==='capacitor'),probe=capacitor?`${capacitor.id}:0`:pins(project.components.find(c=>c.type==='resistor')||project.components.find(c=>c.type==='source'))[0];const metric=document.createElement('div');metric.className='metric';const title=document.createElement('span');title.textContent=`${capacitor?.label||probe.split(':')[0]} · pin 1 to ground`;const value=document.createElement('strong');value.textContent=fmt(dc.voltages[probe],'V');const caption=document.createElement('small');caption.textContent='DC operating point';metric.append(title,value,caption);host.append(metric);const chart=el('svg',{viewBox:'0 0 620 140',class:'plot',role:'img','aria-label':'Voltage step response over 20 milliseconds'});const values=tr.samples.map(s=>s.voltages[probe]),lo=Math.min(0,...values),hi=Math.max(.001,...values);[0,1,2,3].forEach(i=>chart.append(el('path',{d:`M38 ${18+i*30} H600`,stroke:'#242426',fill:'none'})));chart.append(el('path',{d:values.map((v,i)=>`${i?'L':'M'}${38+i/(values.length-1)*560} ${108-(v-lo)/(hi-lo)*85}`).join(' '),stroke:'#fff','stroke-width':2,fill:'none'}));chart.append(el('text',{x:38,y:132,fill:'#777','font-size':10},'0 ms'));chart.append(el('text',{x:562,y:132,fill:'#777','font-size':10},'20 ms'));chart.append(el('text',{x:1,y:20,fill:'#aaa','font-size':10},fmt(hi,'V')));host.append(chart);const detail=document.createElement('div');detail.className='result-note';detail.textContent='STEP RESPONSE / Zero initial capacitor voltage · backward Euler · 50 µs step. Ideal linear components only.';host.append(detail);}
$('#export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}));a.href=url;a.download='orbit-circuit.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);tell('Project exported.');};
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>200000)throw Error('Project file is too large.');const next=validate(JSON.parse(await file.text()));boardEvents.cancel();clearWireGesture({clearPending:true});drag=null;pan=null;checkpoint();project=next;selected=null;pending=null;render();tell('Project imported.');}catch(err){tell(err.message);}e.target.value='';};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(wireGesture||drag||pan)cancelActiveGesture();else{pending=null;render();}}if((e.metaKey||e.ctrlKey)&&e.key==='z'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#undo').click();}});
render();tell('RC filter ready. Press Run simulation to see its response.');

function zoom(f){const w=Math.max(300,Math.min(1800,view.w*f)),h=w*560/900;view.x+=(view.w-w)/2;view.y+=(view.h-h)/2;view.w=w;view.h=h;$('.zoom-readout').textContent=Math.round(900/w*100)+'%';render();}
$('[aria-label="Zoom in"]').onclick=()=>zoom(.8);
$('[aria-label="Zoom out"]').onclick=()=>zoom(1.25);
$('[aria-label="Fit design to screen"]').onclick=()=>{view={x:0,y:0,w:900,h:560};$('.zoom-readout').textContent='100%';render();};
svg.addEventListener('wheel',e=>{e.preventDefault();if(mode!=='board')zoom(e.deltaY<0?.9:1.1);},{passive:false});
$('.palette-search input').oninput=e=>document.querySelectorAll('[data-add]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(e.target.value.toLowerCase()));
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.code==='Space'){e.preventDefault();space=true;}if(mode!=='board'&&(e.metaKey||e.ctrlKey)&&e.key==='Enter')$('#run').click();if(e.key==='/'&&mode!=='board'){e.preventDefault();$('.palette-search input').focus();}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;pan=null;}});
window.addEventListener('blur',()=>{space=false;cancelActiveGesture();});
const collapse=$('[aria-label="Collapse results"]');if(collapse){collapse.onclick=()=>{$('#results').hidden=!$('#results').hidden;collapse.setAttribute('aria-expanded',String(!$('#results').hidden));};}
